<template><div class="work-experience-list"><article v-for="item in workExperience" :key="item.id" class="resume-work-item"><div class="resume-work-period"><span class="kind">{{ t(item.category === 'research' ? 'Research' : 'Employment') }}</span><time>{{ displayRange(item) }}</time></div><div><h3>{{ localized(item, 'title') }}</h3><p><a v-if="organisationUrl(item)" class="organisation organisation-link" :href="organisationUrl(item)" target="_blank" rel="noopener noreferrer">{{ item.organisation }} <ExternalLink :size="12" /></a><span v-else class="organisation">{{ item.organisation }}</span> · {{ item.location }}</p><p>{{ localized(item, 'description') }}</p><ul v-if="localizedHighlights(item).length"><li v-for="highlight in localizedHighlights(item)" :key="highlight">{{ highlight }}</li></ul><a v-if="item.linkHref" class="experience-reference-link" :href="item.linkHref" target="_blank" rel="noopener noreferrer">{{ localized(item, 'linkLabel') || t('Related link') }} <ExternalLink :size="13" /></a></div></article></div></template>
<script setup>
import { computed } from 'vue'; import { ExternalLink } from 'lucide-vue-next'; import { useExperienceStore } from '../composables/useExperienceStore'; import { organisationLinks } from '../data/portfolio'; import { useLocale } from '../composables/useLocale'
const { experiences } = useExperienceStore(); const { locale, t } = useLocale(); const localized = (item, field) => locale.value === 'sv' ? (item.translations?.sv?.[field] || t(item[field])) : item[field]; const localizedHighlights = (item) => locale.value === 'sv' && item.translations?.sv?.highlights?.length ? item.translations.sv.highlights : item.highlights; const workExperience = computed(() => experiences.value.filter((item) => item.category === 'professional' || item.category === 'research')); const formatDate = (value) => new Intl.DateTimeFormat(locale.value === 'sv' ? 'sv-SE' : 'en-GB', { ...(value.length === 10 ? { day: 'numeric' } : {}), month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${value.length === 7 ? `${value}-01` : value}T00:00:00Z`)); const displayRange = (item) => `${item.startDate ? formatDate(item.startDate) : item.start} - ${item.endDate ? formatDate(item.endDate) : t(item.end)}`; const organisationUrl = (item) => item.organisationHref || organisationLinks[item.organisation]
</script>
